    d: [['Faro', '12 V 60/50 W (también 65/55 o 45/40 W según versión)', 'MAN'], ['Intermitentes', '12 V 21 W; laterales 5 W', 'MAN'], ['Freno / posición', '12 V 21/5 W', 'MAN'], ['Retroceso', '12 V 21 W u 8 W', 'MAN'], ['Patente / interior', '12 V 5 W', 'MAN']],
