    d: [['Palancas', '3: salida del aire, recirculación o aire exterior, temperatura (foto)', 'USR'], ['Ventilador', 'Perilla OFF + 3 velocidades (foto)', 'USR'], ['Accionamiento', 'Por cables', 'MAN']],
